PAYLOADS={'src/analytics/__init__.py': '"""Nhận diện, thống kê và kiểm tra độ vững. Chưa triển khai đánh giá ngoài mẫu 70/30; không có mô hình học máy Q4."""\n', 'src/analytics/event_study.py': '"""Lợi suất từ mở cửa t+1; loại cửa sổ thiếu/lỗi và không dùng tương lai sau asof."""\nimport numpy as np\nimport pandas as pd\nfrom analytics.radar import infer_market_days, _valid_rows\nfrom analytics.multiple_testing import fdr_by\n\n\ndef event_outcomes(frames, events, asof, issues=None, horizons=(1,3,5,10,20), fee_bps=20, th=None):\n    from finance.candles import Thresholds\n    from finance.patterns import pattern_catalog\n    th=th or Thresholds()\n    if not 0 <= fee_bps < 10000: raise ValueError(\'Chi phí phải trong khoảng 0 đến dưới 10000 bps\')\n    if not horizons or any(int(h)!=h or h<1 for h in horizons): raise ValueError(\'Kỳ hạn phải là số nguyên dương\')\n    frames={s:f.loc[f.index<=pd.Timestamp(asof)].sort_index() for s,f in frames.items()}\n    calendar=infer_market_days(frames)\n    cat=pattern_catalog(\'pattern\').set_index(\'name\')\n    reversals=set(cat.index)-{\'doji\',\'dragonfly_doji\',\'gravestone_doji\',\'long_legged_doji\',\'spinning_top\',\'marubozu_white\',\'marubozu_black\'}\n    rows=[];fee=fee_bps/20000\n    chosen=events[(events.kind==\'pattern\')&(events.date<=pd.Timestamp(asof))]\n    for symbol,group in chosen.groupby(\'symbol\'):\n        if symbol not in frames: raise ValueError(\'Mã không có dữ liệu: \'+symbol)\n        f=frames[symbol].reindex(calendar)\n        present=pd.Series(calendar.isin(frames[symbol].index),index=calendar)\n        valid=_valid_rows(f)\n        if issues is not None and not issues.empty:\n            bad=pd.to_datetime(issues.loc[(issues.symbol==symbol)&(issues.severity==\'error\'),\'trading_date\'])\n            valid &= ~calendar.isin(bad)\n        logret=np.log(f.close.where(valid)/f.close.where(valid).shift(1))\n        trend=logret.rolling(th.trend_window).mean()/logret.rolling(th.trend_window).std()*np.sqrt(th.trend_window)\n        for h in horizons:\n            enough=pd.Series(np.arange(len(calendar))+h<len(calendar),index=calendar)\n            physical=present.rolling(h).sum().shift(-h).eq(h)\n            eligible=valid.rolling(h).sum().shift(-h).eq(h)\n            gross=f.close.shift(-h)/f.open.shift(-1)-1\n            net=f.close.shift(-h)*(1-fee)/(f.open.shift(-1)*(1+fee))-1\n            mae=(f.low.rolling(h).min().shift(-h)/f.open.shift(-1)-1).clip(upper=0)\n            for name,signals in group.groupby(\'name\'):\n                if name not in cat.index: continue\n                info=cat.loc[name];n=int(info.candles)\n                history=valid.rolling(max(th.avg_window,th.trend_window+1)+n).sum().eq(max(th.avg_window,th.trend_window+1)+n)\n                base=eligible&history\n                direction=1 if info.bias==\'bullish\' else -1 if info.bias==\'bearish\' else np.nan\n                trend_at_signal=trend.shift(n)\n                condition=(trend_at_signal<=-th.trend_t) if info.bias==\'bullish\' else (trend_at_signal>=th.trend_t) if info.bias==\'bearish\' else pd.Series(True,index=calendar)\n                conditional=base&condition if name in reversals else base\n                base_net=net[base].mean();cond_net=net[conditional].mean()\n                hit=(gross>0) if direction==1 else (gross<0)\n                base_hit=hit[base].mean() if base.any() and np.isfinite(direction) else np.nan\n                cond_hit=hit[conditional].mean() if conditional.any() and np.isfinite(direction) else np.nan\n                for e in signals.itertuples(index=False):\n                    day=pd.Timestamp(e.date)\n                    r=dict(symbol=symbol,name=name,name_vi=e.name_vi,bias=e.bias,date=day,horizon=int(h),status=\'pending\',gross=np.nan,net=np.nan,mae=np.nan,entry_date=pd.NaT,exit_date=pd.NaT,\n                           excess=np.nan,conditional_excess=np.nan,oriented_excess=np.nan,oriented_conditional_excess=np.nan,direction_hit=np.nan,baseline_hit=base_hit,conditional_baseline_hit=cond_hit,\n                           baseline_net=base_net,conditional_baseline_net=cond_net,n_baseline=int(base.sum()),n_conditional_baseline=int(conditional.sum()))\n                    if day not in calendar: r[\'status\']=\'invalid\'\n                    elif enough.loc[day]:\n                        if not physical.loc[day]: r[\'status\']=\'missing\'\n                        elif not eligible.loc[day]: r[\'status\']=\'invalid\'\n                        else:\n                            pos=calendar.get_loc(day)\n                            r.update(status=\'evaluated\',gross=float(gross.loc[day]),net=float(net.loc[day]),mae=float(mae.loc[day]),entry_date=calendar[pos+1],exit_date=calendar[pos+h])\n                            r[\'excess\']=r[\'net\']-base_net;r[\'conditional_excess\']=r[\'net\']-cond_net\n                            r[\'oriented_excess\']=direction*r[\'excess\'];r[\'oriented_conditional_excess\']=direction*r[\'conditional_excess\']\n                            r[\'direction_hit\']=float(r[\'gross\']*direction>0) if np.isfinite(direction) else np.nan\n                    rows.append(r)\n    columns=[\'symbol\',\'name\',\'name_vi\',\'bias\',\'date\',\'horizon\',\'status\',\'gross\',\'net\',\'mae\',\'entry_date\',\'exit_date\',\'excess\',\'conditional_excess\',\'oriented_excess\',\'oriented_conditional_excess\',\'direction_hit\',\'baseline_hit\',\'conditional_baseline_hit\',\'baseline_net\',\'conditional_baseline_net\',\'n_baseline\',\'n_conditional_baseline\']\n    return pd.DataFrame(rows,columns=columns)\n\n\ndef summarize_events(outcomes, calendar=None, block_size=20, resamples=1000):\n    from analytics.inference import block_test\n    rows=[]\n    if outcomes.empty: return pd.DataFrame()\n    for (name,h),g in outcomes.groupby([\'name_vi\',\'horizon\']):\n        good=g[g.status==\'evaluated\']\n        daily=good.groupby(\'date\').excess.mean().dropna().to_numpy()\n        # Pandas Copy-on-Write có thể trả mảng chỉ đọc; tạo mảng mới.\n        daily = np.where(np.abs(daily) < 1e-12, 0.0, daily)\n        tested=block_test(good.groupby(\'date\').excess.mean(),calendar,block_size,resamples) if len(good)>=30 else dict(low=np.nan,high=np.nan,p=np.nan)\n        lower,upper,p=tested[\'low\'],tested[\'high\'],tested[\'p\']\n        rows.append({\'Mẫu hình\':name,\'Số phiên\':h,\'Tổng nhãn\':len(g),\'Đủ dữ liệu\':len(good),\n                     \'Chưa đủ tương lai\':int(g.status.eq(\'pending\').sum()),\'Loại thiếu/lỗi\':int(g.status.isin([\'missing\',\'invalid\']).sum()),\n                     \'Lợi suất giá TB (%)\':good.gross.mean()*100,\'Long sau phí TB (%)\':good.net.mean()*100,\n                     \'Tỷ lệ giá tăng (%)\':good.gross.gt(0).mean()*100 if len(good) else np.nan,\n                     \'Bất lợi TB (%)\':good.mae.mean()*100,\'Chênh nền TB theo ngày (%)\':daily.mean()*100 if len(daily) else np.nan,\n                     \'CI95 dưới (%)\':lower*100,\'CI95 trên (%)\':upper*100,\'p bootstrap\':p})\n    result=pd.DataFrame(rows)\n    extra=[]\n    for (name,h),g in outcomes.groupby([\'name_vi\',\'horizon\']):\n        good=g[g.status==\'evaluated\'];bias=g.bias.iloc[0] if \'bias\' in g else \'neutral\'\n        row={\'Mẫu hình\':name,\'Số phiên\':h,\'bias\':bias}\n        for label,column in [(\'all\',\'oriented_excess\'),(\'trend\',\'oriented_conditional_excess\')]:\n            series=good.groupby(\'date\')[column].mean() if column in good and bias!=\'neutral\' else pd.Series(dtype=float)\n            test=block_test(series,calendar,block_size,resamples,one_sided=True) if len(good)>=30 else dict(mean=series.mean(),low=np.nan,high=np.nan,p=np.nan,n_dates=len(series))\n            for key,val in test.items():row[f\'{label}_{key}\']=val\n        if \'direction_hit\' in good:\n            row[\'direction_hit_rate\']=good.direction_hit.mean()\n            row[\'baseline_direction_rate\']=good.baseline_hit.mean()\n            row[\'trend_baseline_direction_rate\']=good.conditional_baseline_hit.mean()\n            row[\'direction_hit_gap\']= (good.direction_hit-good.baseline_hit).mean()\n            row[\'trend_direction_hit_gap\']=(good.direction_hit-good.conditional_baseline_hit).mean()\n        extra.append(row)\n    result=result.merge(pd.DataFrame(extra),on=[\'Mẫu hình\',\'Số phiên\'])\n    result[\'q BY\']=fdr_by(result[\'p bootstrap\'])\n    return result\n', 'src/analytics/inference.py': '"""Bootstrap vòng tròn trên LỊCH đầy đủ; giữ ngày không tín hiệu trong khối."""\nimport numpy as np\nimport pandas as pd\n\n\ndef block_test(series, calendar=None, block_size=20, resamples=1000, seed=2026, one_sided=False):\n    series=series.groupby(level=0).mean().sort_index()\n    if calendar is not None:series=series.reindex(pd.DatetimeIndex(calendar))\n    values=series.to_numpy(dtype=float,copy=True);values[np.abs(values)<1e-12]=0\n    finite=np.isfinite(values);estimate=float(values[finite].mean()) if finite.any() else np.nan\n    if finite.sum()<20:return dict(mean=estimate,low=np.nan,high=np.nan,p=np.nan,n_dates=int(finite.sum()))\n    if block_size<1 or resamples<99:raise ValueError(\'block_size >=1 và resamples >=99\')\n    n=len(values);length=min(block_size,n);rng=np.random.default_rng(seed)\n    collected=[]\n    for offset in range(0,resamples,128):\n        batch=min(128,resamples-offset)\n        starts=rng.integers(0,n,size=(batch,int(np.ceil(n/length))))\n        indices=((starts[:,:,None]+np.arange(length))%n).reshape(batch,-1)[:,:n]\n        samples=values[indices];counts=np.isfinite(samples).sum(axis=1)\n        collected.append(np.divide(np.nansum(samples,axis=1),counts,out=np.full(batch,np.nan),where=counts>0))\n    means=np.concatenate(collected)\n    means=means[np.isfinite(means)]\n    if len(means)<resamples*.8:return dict(mean=estimate,low=np.nan,high=np.nan,p=np.nan,n_dates=int(finite.sum()))\n    low,high=np.quantile(means,[.025,.975]);centered=means-estimate\n    extreme=centered>=estimate if one_sided else np.abs(centered)>=abs(estimate)\n    return dict(mean=estimate,low=float(low),high=float(high),p=(1+int(extreme.sum()))/(len(means)+1),n_dates=int(finite.sum()))\n', 'src/analytics/multiple_testing.py': '"""Benjamini–Yekutieli cho họ kiểm định nhiều mẫu hình × kỳ nắm giữ."""\nimport numpy as np\n\n\ndef fdr_by(values, n_tests=None):\n    values=np.asarray(values,dtype=float)\n    result=np.full(len(values),np.nan);valid=np.flatnonzero(np.isfinite(values))\n    if not len(valid):return result\n    order=valid[np.argsort(values[valid])];n=len(order) if n_tests is None else int(n_tests)\n    if n<len(valid):raise ValueError("n_tests nhỏ hơn số kiểm định hợp lệ")\n    if ((values[valid]<0)|(values[valid]>1)).any():raise ValueError("p-value ngoài [0,1]")\n    adjusted=values[order]*n*sum(1/i for i in range(1,n+1))/np.arange(1,len(order)+1)\n    result[order]=np.minimum(1,np.minimum.accumulate(adjusted[::-1])[::-1])\n    return result\n', 'src/analytics/study.py': '"""Xuất Q1–Q3 có cấu hình cố định; không chọn ngưỡng dựa trên kết quả."""\nfrom dataclasses import asdict, replace\nimport numpy as np\nimport pandas as pd\nfrom finance.candles import Thresholds\nfrom finance.patterns import pattern_catalog\nfrom analytics.radar import build_radar, infer_market_days\nfrom analytics.event_study import event_outcomes, summarize_events\nfrom analytics.setup_probability import build_setup_outcomes, summarize_setups\nfrom analytics.multiple_testing import fdr_by\n\nHORIZONS=(1,3,5,10,20)\nFEES=(20,40)\n\n\ndef q1_tables(events):\n    patterns=events[events.kind==\'pattern\'].copy()\n    patterns[\'year\']=pd.to_datetime(patterns.date).dt.year\n    by_year=pd.crosstab(patterns.name_vi,patterns.year).reindex(pattern_catalog(\'pattern\').name_vi,fill_value=0)\n    by_symbol=pd.crosstab(patterns.name_vi,patterns.symbol).reindex(pattern_catalog(\'pattern\').name_vi,fill_value=0)\n    return by_year,by_symbol\n\n\ndef q2_tables(frames,events,asof,issues=None,horizons=HORIZONS,fees=FEES,resamples=1000,block_size=20):\n    catalog=pattern_catalog(\'pattern\');calendar=infer_market_days({s:f.loc[f.index<=asof] for s,f in frames.items()})\n    summaries=[];details=[]\n    index=pd.MultiIndex.from_product([catalog.name_vi,horizons],names=[\'Mẫu hình\',\'Số phiên\'])\n    for fee in fees:\n        outcomes=event_outcomes(frames,events,asof,issues,horizons,fee)\n        result=summarize_events(outcomes,calendar,block_size,resamples)\n        if result.empty:result=pd.DataFrame(index=index).reset_index()\n        else:result=result.set_index([\'Mẫu hình\',\'Số phiên\']).reindex(index).reset_index()\n        result[\'bias\']=result[\'Mẫu hình\'].map(catalog.set_index(\'name_vi\').bias)\n        result[\'fee_bps\']=fee\n        for col in [\'Tổng nhãn\',\'Đủ dữ liệu\',\'Chưa đủ tương lai\',\'Loại thiếu/lỗi\']:\n            result[col]=result[col].fillna(0).astype(int) if col in result else 0\n        for col in [\'all_p\',\'trend_p\']:\n            if col not in result: result[col]=np.nan\n        summaries.append(result);details.append(outcomes.assign(fee_bps=fee))\n    result=pd.concat(summaries,ignore_index=True)\n    # Họ kiểm định được chốt trước, gồm cả nhãn không đủ số quan sát.\n    family=int(catalog.bias.ne(\'neutral\').sum())*len(horizons)*len(fees)*2\n    combined=np.column_stack([result.all_p,result.trend_p]).reshape(-1)\n    q=fdr_by(combined,n_tests=family).reshape(-1,2)\n    result[\'all_q_fixed\']=q[:,0];result[\'trend_q_fixed\']=q[:,1]\n    return result,pd.concat(details,ignore_index=True),family\n\n\ndef sensitivity_tables(frames,asof,issues=None):\n    base=Thresholds();scenarios=[(\'default\',base)]\n    for field,values in [(\'doji_k\',(.05,.15)),(\'trend_t\',(.75,1.25)),(\'avg_window\',(20,)),(\'strict_gap\',(True,))]:\n        scenarios += [(f\'{field}={value}\',replace(base,**{field:value})) for value in values]\n    counts=[];setups=[]\n    for label,th in scenarios:\n        radar=build_radar(frames,asof,issues,th=th)\n        c=radar.events.groupby([\'kind\',\'name\']).size().rename(\'n\').reset_index().assign(scenario=label)\n        counts.append(c)\n        q3=summarize_setups(build_setup_outcomes(frames,asof,issues,th=th)).assign(scenario=label,parameters=str(asdict(th)))\n        setups.append(q3)\n    return pd.concat(counts,ignore_index=True),pd.concat(setups,ignore_index=True)\n', 'src/analytics/setup_probability.py': '"""Tần suất hoàn thành setup Sao mai/Sao hôm ở đúng phiên thị trường kế tiếp."""\nfrom statistics import NormalDist\n\nimport numpy as np\nimport pandas as pd\n\nfrom analytics.radar import build_radar\n\nPAIRS = {\n    "morning_star_setup": ("morning_star", "Sao mai"),\n    "evening_star_setup": ("evening_star", "Sao hôm"),\n}\nOUTCOME_COLS = ["symbol", "setup", "setup_date", "next_date", "status"]\n\n\ndef wilson_interval(successes, total, confidence=0.95):\n    if not 0 < confidence < 1:\n        raise ValueError("confidence phải nằm giữa 0 và 1")\n    if total < 0 or not 0 <= successes <= total:\n        raise ValueError("Cần 0 <= successes <= total")\n    if total == 0:\n        return np.nan, np.nan\n    z = NormalDist().inv_cdf((1 + confidence) / 2)\n    p = successes / total\n    denominator = 1 + z * z / total\n    center = (p + z * z / (2 * total)) / denominator\n    half = z * np.sqrt(p * (1 - p) / total + z * z / (4 * total * total)) / denominator\n    return max(0.0, center - half), min(1.0, center + half)\n\n\ndef build_setup_outcomes(frames, asof, issues=None, th=None):\n    radar = build_radar(frames, asof, issues, th)\n    events = radar.events\n    setups = events[events["kind"] == "setup"]\n    confirmed = set(events.loc[events["kind"] == "pattern", ["symbol", "date", "name"]].itertuples(index=False, name=None))\n    blocked = set()\n    if issues is not None and not issues.empty:\n        errors = issues[issues["severity"] == "error"]\n        blocked = set(zip(errors["symbol"], pd.to_datetime(errors["trading_date"])))\n    rows = []\n    for event in setups.itertuples(index=False):\n        if event.name not in PAIRS:\n            continue\n        position = radar.market_days.get_loc(event.date)\n        next_date = pd.NaT\n        if position + 1 == len(radar.market_days):\n            status = "pending"\n        else:\n            next_date = radar.market_days[position + 1]\n            frame = frames[event.symbol]\n            if next_date not in frame.index:\n                status = "missing_next_bar"\n            else:\n                o, h, l, c = frame.loc[next_date, ["open", "high", "low", "close"]].to_numpy(dtype=float)\n                valid = (\n                    np.isfinite([o, h, l, c]).all()\n                    and min(o, h, l, c) > 0\n                    and h >= max(o, c) and l <= min(o, c)\n                    and (event.symbol, next_date) not in blocked\n                )\n                if not valid:\n                    status = "invalid_next_bar"\n                else:\n                    target = PAIRS[event.name][0]\n                    status = "completed" if (event.symbol, next_date, target) in confirmed else "not_completed"\n        rows.append((event.symbol, event.name, event.date, next_date, status))\n    return pd.DataFrame(rows, columns=OUTCOME_COLS)\n\n\ndef summarize_setups(outcomes, confidence=0.95):\n    rows = []\n    for name, (_, label) in PAIRS.items():\n        counts = outcomes.loc[outcomes["setup"] == name, "status"].value_counts()\n        successes = int(counts.get("completed", 0))\n        evaluated = successes + int(counts.get("not_completed", 0))\n        pending = int(counts.get("pending", 0))\n        excluded = int(counts.get("missing_next_bar", 0) + counts.get("invalid_next_bar", 0))\n        low, high = wilson_interval(successes, evaluated, confidence)\n        rows.append({\n            "setup": name, "name_vi": label,\n            "n_total": int(counts.sum()), "n_evaluated": evaluated,\n            "n_completed": successes, "n_pending": pending, "n_excluded": excluded,\n            "probability": successes / evaluated if evaluated else np.nan,\n            "ci_low": low, "ci_high": high,\n        })\n    return pd.DataFrame(rows)\n', 'src/analytics/radar.py': '"""Tạo bảng radar từ nến đã lưu. Hàm thuần, không I/O và không ước lượng hiệu quả đầu tư."""\nfrom dataclasses import dataclass\nimport math\n\nimport numpy as np\nimport pandas as pd\n\nfrom finance.candles import Thresholds\nfrom finance.patterns import detect_patterns, detect_setups, pattern_catalog\n\nEVENT_COLS = ["symbol", "date", "name", "name_vi", "bias", "kind", "confirmation"]\nLATEST_COLS = ["symbol", "data_date", "close", "change_pct", "volume", "patterns", "setups", "status"]\n\n\n@dataclass\nclass RadarResult:\n    latest: pd.DataFrame\n    events: pd.DataFrame\n    missing_sessions: pd.DataFrame\n    market_days: pd.DatetimeIndex\n\n\ndef infer_market_days(frames) -> pd.DatetimeIndex:\n    """Lịch ước lượng từ ngày xuất hiện ở ít nhất một nửa số mã có dữ liệu.\n\n    Đây không phải lịch chính thức. Một ngày thiếu ở toàn bộ nhóm mã không thể được phát hiện.\n    """\n    available = [frame for frame in frames.values() if not frame.empty]\n    if not available:\n        return pd.DatetimeIndex([])\n    counts = pd.concat([pd.Series(1, index=frame.index.unique()) for frame in available]).groupby(level=0).sum()\n    return pd.DatetimeIndex(counts[counts >= max(1, math.ceil(len(available) / 2))].index).sort_values()\n\n\ndef _valid_rows(frame):\n    px = frame[["open", "high", "low", "close"]].astype(float)\n    return (\n        np.isfinite(px).all(axis=1) & (px > 0).all(axis=1)\n        & (px["high"] >= px[["open", "close"]].max(axis=1))\n        & (px["low"] <= px[["open", "close"]].min(axis=1))\n    )\n\n\ndef build_radar(frames, asof, issues=None, th=None) -> RadarResult:\n    th = th or Thresholds()\n    asof = pd.Timestamp(asof).normalize()\n    # Cắt trước khi suy lịch và nhận diện để không dùng ngày sau thời điểm đang xem.\n    frames = {symbol: frame.loc[frame.index <= asof].copy() for symbol, frame in frames.items()}\n    market_days = infer_market_days(frames)\n    catalog = pattern_catalog().set_index("name")\n    event_rows, latest_rows, missing_rows = [], [], []\n    for symbol, frame in frames.items():\n        if frame.empty:\n            latest_rows.append([symbol, pd.NaT, np.nan, np.nan, np.nan, "", "", "Chưa có dữ liệu"])\n            continue\n        original_last = frame.index.max()\n        valid = _valid_rows(frame)\n        if issues is not None and not issues.empty:\n            rejected_dates = pd.to_datetime(issues.loc[\n                (issues["symbol"] == symbol) & (issues["severity"] == "error"), "trading_date"\n            ])\n            valid &= ~frame.index.isin(rejected_dates)\n        clean = frame.loc[valid]\n        span = market_days[(market_days >= frame.index.min()) & (market_days <= original_last)]\n        for day in span.difference(frame.index):\n            missing_rows.append((symbol, day, "Thiếu so với lịch ước lượng từ các mã trong rổ"))\n        present = pd.Series(False, index=market_days)\n        present.loc[present.index.intersection(clean.index)] = True\n        eligible = {}\n        for candles in (1, 2, 3):\n            # trend_window lợi suất cần trend_window + 1 giá trước mẫu hình.\n            width = max(th.avg_window, th.trend_window + 1) + candles\n            eligible[candles] = present.rolling(width, min_periods=width).sum().eq(width)\n        current_patterns, current_setups = [], []\n        if not clean.empty:\n            for kind, signals in (("pattern", detect_patterns(clean, th)), ("setup", detect_setups(clean, th))):\n                for name in signals.columns:\n                    info = catalog.loc[name]\n                    mask = eligible[int(info["candles"])].reindex(signals.index, fill_value=False)\n                    dates = signals.index[signals[name] & mask]\n                    for day in dates:\n                        confirmation = ""\n                        if kind == "setup":\n                            position = clean.index.get_loc(day)\n                            first = clean.iloc[position - 1]\n                            midpoint = (first["open"] + first["close"]) / 2\n                            if info["bias"] == "bullish":\n                                confirmation = f"Phiên kế tiếp: nến tăng và đóng cửa > {midpoint:,.2f}"\n                            else:\n                                confirmation = f"Phiên kế tiếp: nến giảm và đóng cửa < {midpoint:,.2f}"\n                        event_rows.append((symbol, day, name, info["name_vi"], info["bias"], kind, confirmation))\n                        if day == asof:\n                            (current_patterns if kind == "pattern" else current_setups).append(info["name_vi"])\n        if original_last != asof:\n            status = "Thiếu nến ngày đang xem"\n        elif asof not in clean.index:\n            status = "Nến bị lỗi chất lượng"\n        elif asof not in eligible[1].index or not eligible[1].loc[asof]:\n            status = "Chưa đủ cửa sổ liên tiếp"\n        else:\n            status = "Đã quét"\n        row = frame.iloc[-1]\n        change = np.nan\n        if asof in market_days and asof in clean.index:\n            pos = market_days.get_loc(asof)\n            if pos > 0 and market_days[pos - 1] in clean.index:\n                change = (clean.loc[asof, "close"] / clean.loc[market_days[pos - 1], "close"] - 1) * 100\n        latest_rows.append((symbol, original_last, row["close"], change, row.get("volume", np.nan),\n                            "; ".join(current_patterns), "; ".join(current_setups), status))\n    events = pd.DataFrame(event_rows, columns=EVENT_COLS).sort_values(["date", "symbol", "name"]).reset_index(drop=True)\n    latest = pd.DataFrame(latest_rows, columns=LATEST_COLS)\n    missing = pd.DataFrame(missing_rows, columns=["symbol", "date", "detail"])\n    return RadarResult(latest, events, missing, market_days)\n', 'src/finance/candles.py': '"""Mô tả hình dạng nến Nhật từ dữ liệu OHLC (lớp tài chính thuần: không đọc/ghi, không gọi API).\n\nĐầu vào: DataFrame có các cột open, high, low, close, **sắp xếp tăng dần theo thời gian**\n(API SSI trả mới nhất trước nên phải sắp xếp trước khi gọi).\n\nNguyên tắc chống nhìn trước tương lai: mọi đại lượng tại dòng t chỉ dùng dữ liệu từ dòng t trở về trước.\nCác đại lượng "tương đối" (thân dài/ngắn, Doji) so với trung bình của `avg_window` nến TRƯỚC đó.\n\nQuy ước màu theo slide S7: Open < Close là nến tăng (white), Open > Close là nến giảm (black).\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nimport numpy as np\nimport pandas as pd\n\nOHLC = ("open", "high", "low", "close")\n\n\n@dataclass(frozen=True)\nclass Thresholds:\n    """Ngưỡng nhận diện. Giá trị là quy tắc vận hành định trước của đồ án, chưa tối ưu theo lợi suất.\n    scripts/run_study.py --sensitivity khảo sát từng tham số riêng, không chọn bộ ngưỡng thắng cuộc.\n    """\n\n    avg_window: int = 10          # số nến trước dùng để tính thân/biên độ trung bình\n    doji_k: float = 0.10          # Doji: thân <= 10% biên độ trung bình\n    long_k: float = 1.0           # thân dài: >= 1,0 x thân trung bình\n    short_k: float = 1.0          # thân ngắn: <= 1,0 x thân trung bình\n    shadow_tiny: float = 0.10     # bóng "rất ngắn": <= 10% biên độ của chính nến\n    shadow_long_mult: float = 2.0  # Hammer/Shooting star: bóng dài >= 2 x thân\n    long_shadow_pct: float = 0.60  # Doji chuồn chuồn/bia mộ: bóng dài >= 60% biên độ\n    legged_pct: float = 0.30       # Doji chân dài: mỗi bóng >= 30% biên độ\n    marubozu_shadow: float = 0.05  # Marubozu: mỗi bóng <= 5% biên độ\n    trend_window: int = 10         # cửa sổ đo xu hướng trước mẫu hình\n    trend_t: float = 1.0           # có xu hướng khi |thống kê t của lợi suất trung bình| >= 1\n    strict_gap: bool = False       # True: Piercing/Dark Cloud phải mở cửa vượt đáy/đỉnh nến trước\n    limit_pct: float = 0.07        # biên độ giá: HOSE 7%, HNX 10%, UPCOM 15%\n    limit_tol: float = 0.005       # sai số làm tròn bước giá khi xác định "gần trần/sàn"\n\n    def __post_init__(self):\n        if self.avg_window < 2 or self.trend_window < 3:\n            raise ValueError("avg_window phải >= 2 và trend_window phải >= 3")\n\n\ndef validate_ohlc(df: pd.DataFrame) -> None:\n    """Báo lỗi rõ ràng nếu dữ liệu không dùng được (thay vì cho ra kết quả sai âm thầm)."""\n    missing = [c for c in OHLC if c not in df.columns]\n    if missing:\n        raise ValueError(f"Thiếu cột: {\', \'.join(missing)}")\n    if not df.index.is_monotonic_increasing:\n        raise ValueError("Dữ liệu phải sắp xếp tăng dần theo thời gian (API trả mới nhất trước)")\n    if df.index.has_duplicates:\n        raise ValueError("Chỉ số thời gian bị trùng")\n    px = df[list(OHLC)]\n    if px.isna().any().any():\n        raise ValueError("Có giá trị thiếu (NaN) trong OHLC")\n    if (px <= 0).any().any():\n        raise ValueError("Có giá không dương trong OHLC")\n    top = df[["open", "close"]].max(axis=1)\n    bottom = df[["open", "close"]].min(axis=1)\n    bad = (df["high"] < top) | (df["low"] > bottom)\n    if bad.any():\n        raise ValueError(f"{int(bad.sum())} nến không hợp lệ: high < max(open, close) hoặc low > min(open, close)")\n\n\ndef describe_candles(\n    df: pd.DataFrame,\n    th: Thresholds | None = None,\n    ref: pd.Series | None = None,\n) -> pd.DataFrame:\n    """Tính các đại lượng mô tả từng nến. Không sửa DataFrame đầu vào.\n\n    ref: giá tham chiếu từng phiên (cùng chỉ số với df) để tính gap và cờ trần/sàn.\n         Mặc định dùng giá đóng cửa hôm trước (lệch ở ngày giao dịch không hưởng quyền).\n    """\n    th = th or Thresholds()\n    validate_ohlc(df)\n    o, h, l, c = (df[k].astype(float) for k in OHLC)\n\n    body_top = o.where(o >= c, c)\n    body_bot = o.where(o <= c, c)\n    body = body_top - body_bot\n    rng = h - l\n    upper = h - body_top\n    lower = body_bot - l\n    pos = rng > 0                 # phiên khóa trần/sàn (O=H=L=C) có biên độ 0: không phải nến hình dạng\n    safe_rng = rng.where(pos)     # NaN khi biên độ bằng 0\n\n    # Trung bình của các nến TRƯỚC (shift 1) để không dùng thông tin của chính nến đang xét.\n    body_avg = body.rolling(th.avg_window).mean().shift(1)\n    range_avg = rng.rolling(th.avg_window).mean().shift(1)\n\n    doji = pos & (body <= th.doji_k * range_avg)\n    long_body = pos & (body > 0) & (body >= th.long_k * body_avg)\n    short_body = pos & (body <= th.short_k * body_avg)\n\n    # Xu hướng: thống kê t của lợi suất log trung bình trong cửa sổ kết thúc tại t.\n    logret = np.log(c / c.shift(1))\n    w = th.trend_window\n    trend_t = logret.rolling(w).mean() / logret.rolling(w).std() * np.sqrt(w)\n\n    ref_s = c.shift(1) if ref is None else ref.reindex(df.index).astype(float)\n    lim = th.limit_pct - th.limit_tol\n\n    out = pd.DataFrame(\n        {\n            "open": o, "high": h, "low": l, "close": c,\n            "body": body, "rng": rng, "upper": upper, "lower": lower,\n            "body_top": body_top, "body_bot": body_bot,\n            "white": c > o, "black": c < o,\n            "body_pct": body / safe_rng,\n            "upper_pct": upper / safe_rng,\n            "lower_pct": lower / safe_rng,\n            "body_avg": body_avg, "range_avg": range_avg,\n            "doji": doji, "long_body": long_body, "short_body": short_body,\n            "trend_t": trend_t,\n            "ref": ref_s,\n            "gap": o / ref_s - 1,\n            "ret_ref": c / ref_s - 1,\n            "limit_up": (c / ref_s - 1) >= lim,      # NaN (thiếu tham chiếu) cho kết quả False\n            "limit_down": (c / ref_s - 1) <= -lim,\n        },\n        index=df.index,\n    )\n    return out\n', 'src/finance/indicators.py': '"""Chỉ báo chỉ dùng dữ liệu đã biết tại từng ngày; không có I/O."""\nimport numpy as np\nimport pandas as pd\n\n\ndef indicators(frame, trend_window=10):\n    c=frame.close.astype(float);r=np.log(c/c.shift(1));volume=frame.volume.astype(float)\n    prior=volume.rolling(20,min_periods=20).mean().shift(1)\n    sd=volume.rolling(20,min_periods=20).std().shift(1)\n    return pd.DataFrame({\'ema20\':c.ewm(span=20,adjust=False,min_periods=20).mean(),\n        \'ema50\':c.ewm(span=50,adjust=False,min_periods=50).mean(),\n        \'volume_z20\':(volume-prior)/sd.replace(0,np.nan),\n        \'volatility20\':r.rolling(20,min_periods=20).std()*np.sqrt(252),\n        \'trend_t\':r.rolling(trend_window).mean()/r.rolling(trend_window).std()*np.sqrt(trend_window)},index=frame.index)\n', 'src/finance/context.py': '"""Bối cảnh và kịch bản minh bạch, chỉ dùng nến đã biết tại ngày phân tích."""\nimport numpy as np\nimport pandas as pd\nfrom finance.indicators import indicators\nfrom finance.patterns import pattern_catalog, detect_patterns\n\n\ndef signal_context(frame, event, asof, market_days):\n    day = pd.Timestamp(event[\'date\'])\n    data = frame.loc[frame.index <= pd.Timestamp(asof)].sort_index()\n    history = data.loc[data.index <= day]\n    if day not in history.index:\n        raise ValueError(\'Thiếu nến tín hiệu\')\n    bar = history.loc[day]\n    info = pattern_catalog().set_index(\'name\').loc[event[\'name\']]\n    prior = history.iloc[:-int(info.candles)]\n    trend = np.nan if len(prior) < 6 else (prior.close.iloc[-1] / prior.close.iloc[-6] - 1) * 100\n    reference = history.iloc[:-1].tail(20)\n    volume_mean = reference.volume.mean() if len(reference) == 20 else np.nan\n    ratio = bar.volume / volume_mean if pd.notna(volume_mean) and volume_mean > 0 else np.nan\n    ema20 = history.close.ewm(span=20, adjust=False, min_periods=20).mean().iloc[-1]\n    ema50 = history.close.ewm(span=50, adjust=False, min_periods=50).mean().iloc[-1]\n    support = reference.low.min() if len(reference) == 20 else np.nan\n    resistance = reference.high.max() if len(reference) == 20 else np.nan\n    bias = event[\'bias\']\n    follow = \'Chờ phiên kế tiếp đóng cửa vượt đỉnh nến tín hiệu.\' if bias == \'bullish\' else \'Chờ phiên kế tiếp đóng cửa dưới đáy nến tín hiệu.\' if bias == \'bearish\' else \'Quan sát giá thoát vùng đỉnh–đáy; đối chiếu xu hướng trước đó.\'\n    if event[\'kind\'] == \'setup\':\n        follow = event.get(\'confirmation\', \'\') or \'Chờ mẫu hình ba nến được xác nhận theo định nghĩa của đồ án.\'\n    future = pd.DatetimeIndex(market_days)\n    future = future[(future > day) & (future <= pd.Timestamp(asof))]\n    status = \'Quan sát\' if bias == \'neutral\' else \'Chờ xác nhận\'\n    if len(future) and bias != \'neutral\':\n        nxt = future[0]\n        if nxt not in data.index:\n            status = \'Thiếu nến xác nhận\'\n        else:\n            row = data.loc[nxt]\n            valid = np.isfinite(row[[\'open\',\'high\',\'low\',\'close\']]).all() and row.low > 0 and row.low <= min(row.open,row.close) and row.high >= max(row.open,row.close)\n            if not valid:\n                status = \'Nến xác nhận không hợp lệ\'\n            elif event[\'kind\'] == \'setup\':\n                patterns = detect_patterns(data.loc[data.index <= nxt])\n                name = event[\'name\'].replace(\'_setup\',\'\')\n                status = \'Đã xác nhận\' if bool(patterns.loc[nxt,name]) else \'Phiên kế tiếp không xác nhận\'\n            else:\n                confirmed = row.close > bar.high if bias == \'bullish\' else row.close < bar.low\n                invalid = row.close < bar.low if bias == \'bullish\' else row.close > bar.high\n                status = \'Mất hiệu lực ở phiên kế tiếp\' if invalid else \'Đã xác nhận\' if confirmed else \'Phiên kế tiếp không xác nhận\'\n    trend_stat=indicators(history).trend_t.iloc[-int(info.candles)-1] if len(history)>int(info.candles) else np.nan\n    return dict(trend_pct=trend, trend_t=trend_stat, ema20=ema20, ema50=ema50, volume_ratio=ratio,\n                support=support, resistance=resistance, high=float(bar.high), low=float(bar.low),\n                close=float(bar.close), status=status, follow=follow,\n                invalidation=float(bar.low if bias == \'bullish\' else bar.high) if bias != \'neutral\' else np.nan)\n', 'src/app/signal_workspace.py': '"""Chi tiết tín hiệu và nghiên cứu lợi suất; UI độc lập với nhận diện mẫu hình."""\nimport json\nimport pandas as pd\nimport plotly.graph_objects as go\nimport streamlit as st\nfrom finance.context import signal_context\nfrom analytics.event_study import event_outcomes, summarize_events\nfrom analytics.radar import build_radar, infer_market_days\nfrom analytics.study import q1_tables\n\nLABELS={\'bullish\':\'Hướng tăng\',\'bearish\':\'Hướng giảm\',\'neutral\':\'Trung tính\'}\n\n\n@st.cache_data(show_spinner=False)\ndef enrich(frames, events, asof, market_days):\n    rows=[]\n    for _,event in events.iterrows():\n        row=event.to_dict()\n        row.update(signal_context(frames[event.symbol],row,asof,market_days))\n        rows.append(row)\n    return pd.DataFrame(rows)\n\n\ndef render_signal_workspace(frames, events, asof, selected, market_days, root, issues=None):\n    with st.expander(\'Kịch bản xử lý & bối cảnh tín hiệu\',expanded=True):\n        st.caption(\'Quy tắc theo dõi học thuật, cần xác nhận bằng giá. Các mức dưới đây chưa được kiểm định như một chiến lược giao dịch.\')\n        prefs=root/\'storage/preferences/watchlist.json\'\n        saved=[]\n        if prefs.exists():\n            try: saved=json.loads(prefs.read_text(encoding=\'utf-8\'))\n            except (ValueError,OSError): st.warning(\'Không đọc được danh sách đã lưu. Có thể chọn lại và lưu.\')\n        watch=st.multiselect(\'Danh sách quan tâm\',selected,default=[s for s in saved if s in selected],key=\'watch_symbols\')\n        if st.button(\'Lưu danh sách quan tâm\',key=\'save_watchlist\'):\n            try:\n                prefs.parent.mkdir(parents=True,exist_ok=True)\n                temp=prefs.with_suffix(\'.tmp\');temp.write_text(json.dumps(watch,ensure_ascii=False),encoding=\'utf-8\');temp.replace(prefs)\n                st.success(\'Đã lưu danh sách vào storage/preferences/watchlist.json\')\n            except OSError as exc: st.error(f\'Không lưu được danh sách: {exc}\')\n        only_watch=st.checkbox(\'Chỉ xem danh sách quan tâm\',key=\'watch_only\')\n        scope=st.radio(\'Phạm vi tín hiệu\',[\'Ngày quét\',\'Lịch sử trong khoảng hiển thị\'],horizontal=True,key=\'signal_scope\')\n        view=events[events.date==asof] if scope==\'Ngày quét\' else events\n        if only_watch: view=view[view.symbol.isin(watch)]\n        if view.empty:\n            st.info(\'Không có tín hiệu phù hợp. Chọn lịch sử hoặc điều chỉnh danh sách quan tâm.\');return\n        enriched=enrich(frames,view,asof,tuple(market_days))\n        direction=st.multiselect(\'Hướng lý thuyết\',list(LABELS.values()),default=list(LABELS.values()),key=\'signal_direction\')\n        state=st.selectbox(\'Trạng thái xác nhận\',[\'Tất cả\',*sorted(enriched.status.unique())],key=\'signal_status\')\n        volume_threshold=st.number_input(\'Ngưỡng khối lượng tự chọn (lần TB20)\',min_value=0.1,max_value=5.0,value=1.2,step=0.1,key=\'volume_threshold\')\n        volume=st.checkbox(\'Lọc theo ngưỡng khối lượng tự chọn\',key=\'signal_volume\')\n        enriched=enriched[enriched.bias.map(LABELS).isin(direction)]\n        if state!=\'Tất cả\': enriched=enriched[enriched.status==state]\n        if volume: enriched=enriched[enriched.volume_ratio>=volume_threshold]\n        if enriched.empty: st.info(\'Không có tín hiệu đáp ứng bộ lọc.\');return\n        enriched=enriched.sort_values([\'date\',\'symbol\'],ascending=[False,True]).reset_index(drop=True)\n        st.download_button(\'Tải danh sách tín hiệu đã lọc\',enriched.to_csv(index=False).encode(\'utf-8-sig\'),\'signal_scenarios.csv\',\'text/csv\',key=\'scenario_csv\')\n        index=st.selectbox(\'Chọn tín hiệu\',range(len(enriched)),format_func=lambda i:f"{enriched.iloc[i].symbol} · {enriched.iloc[i].date:%d/%m/%Y} · {enriched.iloc[i].name_vi}",key=\'scenario_index\')\n        r=enriched.iloc[index]\n        number=lambda x:\'Chưa đủ dữ liệu\' if pd.isna(x) else f\'{x:,.2f}\'\n        st.markdown(f\'**{r.symbol} · {r.name_vi} · {LABELS[r.bias]}**\')\n        st.write(\'Trạng thái:\',r.status)\n        st.write(\'Theo dõi:\',r.follow)\n        st.write(\'Mức vô hiệu tham khảo:\',number(r.invalidation) if r.bias!=\'neutral\' else \'Chưa có hướng; theo dõi cả đỉnh và đáy.\')\n        context=pd.DataFrame([\n            [\'Lợi suất 5 phiên trước mẫu hình (bổ trợ)\' ,number(r.trend_pct)+\' %\'],\n            [\'Thống kê t xu hướng 10 phiên trước mẫu hình\',number(r.trend_t)],\n            [\'EMA20 tại ngày tín hiệu\',number(r.ema20)],[\'EMA50 tại ngày tín hiệu\',number(r.ema50)],\n            [\'Giá so với EMA20\', \'Chưa đủ dữ liệu\' if pd.isna(r.ema20) else \'Trên EMA20\' if r.close>r.ema20 else \'Không vượt EMA20\'],\n            [\'Khối lượng / TB20 phiên trước\',number(r.volume_ratio)+\' lần\'],\n            [\'Hỗ trợ: đáy 20 phiên trước\',number(r.support)],[\'Kháng cự: đỉnh 20 phiên trước\',number(r.resistance)]],columns=[\'Bối cảnh\',\'Giá trị\'])\n        st.dataframe(context,hide_index=True,width=\'stretch\')\n        st.caption(\'Hỗ trợ/kháng cự là cực trị 20 phiên trước, chưa phải vùng giá đã xác nhận. Bối cảnh được tính tại ngày tín hiệu; trạng thái chỉ đối chiếu đúng phiên thị trường kế tiếp đã biết đến ngày quét.\')\n        f=frames[r.symbol].loc[lambda x:x.index<=asof].copy()\n        f[\'ema20\']=f.close.ewm(span=20,adjust=False,min_periods=20).mean()\n        f[\'ema50\']=f.close.ewm(span=50,adjust=False,min_periods=50).mean()\n        f=f.loc[f.index>=pd.Timestamp(r.date)-pd.Timedelta(days=90)]\n        fig=go.Figure(go.Candlestick(x=f.index,open=f.open,high=f.high,low=f.low,close=f.close,name=r.symbol,increasing_line_color=\'#159b7e\',decreasing_line_color=\'#f05270\'))\n        for name,color in [(\'ema20\',\'#6d67df\'),(\'ema50\',\'#e6a23c\')]: fig.add_scatter(x=f.index,y=f[name],name=name.upper(),mode=\'lines\',line={\'color\':color,\'width\':1})\n        fig.add_hline(y=r.high,line_dash=\'dash\',line_color=\'#159b7e\',annotation_text=\'Đỉnh nến tín hiệu\')\n        fig.add_hline(y=r.low,line_dash=\'dash\',line_color=\'#ff244e\',annotation_text=\'Đáy nến tín hiệu\')\n        if r.bias!=\'neutral\':\n            level=r.invalidation\n            fig.add_hrect(y0=level*.995,y1=level*1.005,fillcolor=\'#ff244e\',opacity=.07,line_width=0)\n        fig.add_scatter(x=[r.date],y=[r.close],mode=\'markers\',name=\'Tín hiệu đang chọn\',marker={\'size\':12,\'color\':\'#ff244e\',\'symbol\':\'diamond\'})\n        fig.update_layout(height=420,xaxis_rangeslider_visible=False,template=\'plotly_white\',font={\'family\':\'Inter\'},legend={\'orientation\':\'h\'},margin={\'t\':25,\'b\':20})\n        st.plotly_chart(fig,width=\'stretch\',key=\'scenario_chart\')\n        st.caption(\'Dải tô là vùng ±0,5% quanh mức vô hiệu để dễ nhìn; chưa phải biên dừng lỗ tối ưu. Với setup Sao mai/Sao hôm, dùng điều kiện xác nhận ghi trong thẻ, không dùng quy tắc vượt đỉnh/đáy chung.\')\n        if st.checkbox(\'Tính thống kê lịch sử của mẫu hình này\', key=\'selected_research\'):\n            if r[\'kind\']==\'setup\':\n                st.info(\'Cảnh báo hai nến: xem tỷ lệ hoàn thành Sao mai/Sao hôm trong mục Thống kê cảnh báo.\')\n            else:\n                _, selected_summary=research(frames,events[events[\'name\']==r[\'name\']],asof,issues,20)\n                st.dataframe(selected_summary,hide_index=True,width=\'stretch\')\n                st.caption(\'Phạm vi: nhóm mã và khoảng hiển thị đang chọn, đến ngày quét; phí hai chiều mặc định 20 bps. Quy tắc xác nhận chung trong thẻ chưa được kiểm định riêng.\')\n\n\n\n@st.cache_data(show_spinner=False)\ndef research(frames,events,asof,issues,fee):\n    result=event_outcomes(frames,events,asof,issues,fee_bps=fee)\n    return result,summarize_events(result,infer_market_days({s:f.loc[f.index<=asof] for s,f in frames.items()}))\n\n\ndef render_event_research(frames,events,asof,issues):\n    with st.expander(\'Hiệu quả sau tín hiệu · 1 / 3 / 5 / 10 / 20 phiên\',expanded=True):\n        scope=st.radio(\'Phạm vi nghiên cứu Q1/Q2\',[\'Toàn bộ lịch sử\',\'Theo khoảng hiển thị\'],horizontal=True,key=\'q2_scope\')\n        if scope==\'Toàn bộ lịch sử\':\n            names=st.session_state.get(\'symbols\',list(frames))\n            events=build_radar(frames,asof,issues).events\n            events=events[events.symbol.isin(names)]\n        years,tickers=q1_tables(events)\n        with st.expander(\'Q1 · Tần suất mẫu hình theo năm và mã\'):\n            st.dataframe(years,width=\'stretch\');st.dataframe(tickers,width=\'stretch\')\n            st.download_button(\'Tải Q1 theo năm\',years.to_csv().encode(\'utf-8-sig\'),\'q1_year.csv\',\'text/csv\',key=\'q1_year_csv\')\n            st.download_button(\'Tải Q1 theo mã\',tickers.to_csv().encode(\'utf-8-sig\'),\'q1_symbol.csv\',\'text/csv\',key=\'q1_symbol_csv\')\n        fee=st.number_input(\'Tổng phí hai chiều giả định (bps)\',min_value=0,max_value=500,value=20,step=5,key=\'event_fee\')\n        st.caption(\'20 bps = 0,20% hai chiều. Vào tại mở cửa phiên kế tiếp, thoát tại đóng cửa phiên thứ 1/3/5/10/20 kể từ lúc vào; phí chia đều cho hai chiều. Chỉ dùng dữ liệu đến ngày quét theo phạm vi Q1/Q2 đã chọn; báo cáo cố định chạy bằng scripts/run_study.py.\')\n        with st.spinner(\'Đang tính lợi suất sau tín hiệu...\'):\n            result,summary=research(frames,events,asof,issues,fee)\n        if summary.empty: st.info(\'Chưa có mẫu hình để thống kê.\');return\n        st.dataframe(summary,hide_index=True,width=\'stretch\')\n        st.download_button(\'Tải nghiên cứu lợi suất CSV\',summary.to_csv(index=False).encode(\'utf-8-sig\'),\'event_summary.csv\',\'text/csv\',key=\'event_summary_csv\')\n        st.download_button(\'Tải từng quan sát lợi suất\',result.to_csv(index=False).encode(\'utf-8-sig\'),\'event_outcomes.csv\',\'text/csv\',key=\'event_rows_csv\')\n        st.info(\'Lợi suất long sau phí là giả định cho mọi nhãn, không phải gợi ý mua khi có mẫu hình giảm. Bất lợi đo đáy thấp nhất so với giá vào, không phải drawdown danh mục. Chưa mô phỏng trượt giá, thanh khoản hoặc khớp lệnh khi khóa trần/sàn; chưa đánh giá ngoài mẫu.\')\n        st.caption(\'Kiểm định thăm dò: trừ lợi suất nền long cùng mã/kỳ hạn từ toàn bộ cửa sổ hợp lệ đến ngày quét; lấy trung bình theo ngày tín hiệu. Bootstrap vòng tròn theo khối 20 phiên lịch ước lượng, giữ cả ngày không có tín hiệu, 1.000 lần; p dùng phân phối bootstrap đã trừ trung bình, q trên UI phụ thuộc phạm vi. Dùng q2_summary.csv từ run_study.py cho báo cáo: họ hướng lý thuyết chốt cả 30 mã, 5 kỳ hạn, 2 mức phí và 2 mức nền. all_mean/trend_mean là chênh nền đổi dấu theo hướng; all_p/trend_p kiểm định một phía. Tỷ lệ đúng hướng là theo nhãn; tương phản kiểm định lấy trọng số đều theo ngày. Chỉ tính CI/p khi có ≥30 nhãn và ≥20 ngày. Lựa chọn khối và tính dừng ảnh hưởng kết quả; chưa đủ để kết luận hiệu quả giao dịch.\')\n', 'scripts/run_study.py': '"""Tái lập Q1–Q3 từ SQLite chỉ đọc, toàn bộ lịch sử và rổ nghiên cứu cố định."""\nfrom pathlib import Path\nimport sys\nROOT=Path(__file__).resolve().parents[1]\nsys.path.insert(0,str(ROOT/\'src\'))\nimport argparse,json,hashlib,platform\nfrom datetime import datetime,timedelta\nfrom contextlib import closing\nimport numpy as np\nimport pandas as pd\nfrom data import db\nfrom data.ingest import load_universe\nfrom analytics.radar import build_radar\nfrom analytics.setup_probability import build_setup_outcomes,summarize_setups\nfrom analytics.study import q1_tables,q2_tables,sensitivity_tables,HORIZONS,FEES\nfrom finance.candles import Thresholds\nfrom dataclasses import asdict\n\n\ndef main():\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--db\',default=\'storage/radar.db\');parser.add_argument(\'--asof\')\n    parser.add_argument(\'--out\',default=\'report/tables\');parser.add_argument(\'--sensitivity\',action=\'store_true\')\n    parser.add_argument(\'--resamples\',type=int,default=39999);parser.add_argument(\'--block-size\',type=int,default=20)\n    args=parser.parse_args()\n    if args.resamples < 99 or args.block_size < 1:\n        parser.error(\'--resamples >= 99 và --block-size >= 1\')\n    path=Path(args.db);path=(ROOT/path).resolve() if not path.is_absolute() else path\n    symbols=list(dict.fromkeys(load_universe(ROOT/\'src/data/universe_vn30.txt\')))\n    if len(symbols)!=30:raise ValueError(\'Luồng báo cáo yêu cầu rổ cố định 30 mã; kiểm tra universe_vn30.txt\')\n    with closing(db.connect_readonly(path)) as conn:\n        conn.execute(\'BEGIN\')\n        frames={s:db.load_ohlc(conn,s) for s in symbols}\n        issues=pd.read_sql_query(\'SELECT symbol,trading_date,check_name AS "check",severity,detail FROM quality_issues\',conn)\n    empty=[s for s,f in frames.items() if f.empty]\n    if empty:raise ValueError(\'Thiếu toàn bộ OHLC cho mã trong rổ cố định: \'+\', \'.join(empty))\n    # Băm dữ liệu đã đọc trong cùng giao dịch, kể cả khi SQLite dùng WAL.\n    frozen=hashlib.sha256()\n    for symbol in symbols:\n        frozen.update(symbol.encode())\n        frozen.update(frames[symbol].to_csv(date_format=\'%Y-%m-%dT%H:%M:%S\').encode())\n    frozen.update(issues.sort_values(list(issues.columns)).to_csv(index=False).encode())\n    now=datetime.now(db.VN);closed=pd.Timestamp(now.date() if now.hour>=15 else now.date()-timedelta(days=1))\n    latest=max(f.index.max() for f in frames.values() if not f.empty)\n    asof=pd.Timestamp(args.asof) if args.asof else min(latest,closed)\n    if asof>closed:raise ValueError(\'Ngày quét vượt ngày đã đóng theo chốt 15:00 UTC+7\')\n    radar=build_radar(frames,asof,issues);out=Path(args.out);out=out if out.is_absolute() else ROOT/out\n    out.mkdir(parents=True,exist_ok=True)\n    def save(name,frame,index=False):\n        frame.to_csv(out/name,index=index,encoding=\'utf-8-sig\');print(name,frame.shape,flush=True)\n    years,tickers=q1_tables(radar.events)\n    save(\'q1_pattern_year.csv\',years,True);save(\'q1_pattern_symbol.csv\',tickers.reindex(columns=symbols,fill_value=0),True)\n    save(\'signals.csv\',radar.events)\n    print(\'Đang tính Q2, kỳ hạn 1/3/5/10/20 và phí 20/40 bps...\',flush=True)\n    q2,details,family=q2_tables(frames,radar.events,asof,issues,resamples=args.resamples,block_size=args.block_size)\n    save(\'q2_summary.csv\',q2);save(\'q2_outcomes.csv\',details)\n    outcomes=build_setup_outcomes(frames,asof,issues)\n    save(\'q3_summary.csv\',summarize_setups(outcomes));save(\'q3_outcomes.csv\',outcomes)\n    if args.sensitivity:\n        counts,prob=sensitivity_tables(frames,asof,issues);save(\'sensitivity_counts.csv\',counts);save(\'sensitivity_q3.csv\',prob)\n    source_files=[p for folder in [\'src/analytics\',\'src/finance\',\'src/data\'] for p in (ROOT/folder).glob(\'*.py\')]+[Path(__file__)]\n    sources={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in source_files}\n    tables={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.glob(\'*.csv\')}\n    manifest=dict(asof=str(asof.date()),universe=symbols,horizons=HORIZONS,fees_bps=FEES,thresholds=asdict(Thresholds()),\n        resamples=args.resamples,block_size=args.block_size,seed=2026,planned_directional_family=family,\n        min_bootstrap_p=1/(args.resamples+1),\n        by_rank1_resolution_floor=family*sum(1/i for i in range(1,family+1))/(args.resamples+1),\n        q_family=\'all 30 symbols pooled; all patterns x horizons x both fee levels x both baselines, directional only\',\n        aggregation=\'long returns/MAE/hit gaps per label; hypothesis contrasts equal-weighted per signal date\',\n        db_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),input_snapshot_sha256=frozen.hexdigest(),source_hashes=sources,table_hashes=tables,\n        python=platform.python_version(),numpy=np.__version__,pandas=pd.__version__,\n        limitations=[\'exploratory in-sample; no Q4\',\'baseline fitted on full closed historical sample\',\'calendar inferred; index membership not point-in-time\',\'simulation calibration does not prove market validity\'])\n    (out/\'manifest.json\').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    print(\'Hoàn tất:\',out)\n\n\nif __name__==\'__main__\':main()\n', 'scripts/research/calibrate.py': '"""DỮ LIỆU MÔ PHỎNG: random walk, kiểm tra null và positive control +3%."""\nfrom pathlib import Path\nimport sys\nROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/\'src\'))\nimport argparse,json,hashlib,platform\nimport numpy as np\nimport pandas as pd\nfrom analytics.radar import build_radar\nfrom analytics.study import q2_tables\nfrom analytics.setup_probability import wilson_interval\n\n\ndef random_walk(seed,days=650,symbols=6):\n    rng=np.random.default_rng(seed);index=pd.bdate_range(\'2020-01-01\',periods=days);frames={}\n    for i in range(symbols):\n        gap=rng.normal(0,.004,days);intraday=rng.normal(0,.012,days)\n        close=100*np.exp(np.cumsum(gap+intraday));prior=np.r_[100,close[:-1]];opening=prior*np.exp(gap)\n        spread=np.abs(rng.normal(.004,.002,days))\n        frames[f\'SIM{i}\']=pd.DataFrame(dict(open=opening,high=np.maximum(opening,close)*(1+spread),low=np.minimum(opening,close)/(1+spread),close=close,volume=rng.lognormal(10,.2,days)),index=index)\n    return frames\n\n\ndef inject(frames,events,effect=.03):\n    output={}\n    for symbol,f in frames.items():\n        flags=np.zeros(len(f));index=f.index\n        for day in events.loc[(events.symbol==symbol)&(events.name==\'bullish_engulfing\'),\'date\']:\n            pos=index.get_loc(day)+1\n            if pos<len(f):flags[pos]=1\n        factor=(1+effect)**np.cumsum(flags);before=factor/(1+effect)**flags\n        g=f.copy();g[\'open\']=f.open*before;g[\'close\']=f.close*factor\n        g[\'high\']=np.maximum(f.high*before,g[[\'open\',\'close\']].max(axis=1));g[\'low\']=np.minimum(f.low*before,g[[\'open\',\'close\']].min(axis=1))\n        output[symbol]=g\n    return output\n\n\ndef main():\n    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument(\'--repetitions\',type=int,default=100);ap.add_argument(\'--resamples\',type=int,default=3999);ap.add_argument(\'--out\',default=\'report/calibration\')\n    args=ap.parse_args();out=Path(args.out);out=out if out.is_absolute() else ROOT/out;out.mkdir(parents=True,exist_ok=True)\n    if args.repetitions < 1 or args.resamples < 99:ap.error(\'--repetitions >= 1 và --resamples >= 99\')\n    rows=[]\n    for trial in range(args.repetitions):\n        frames=random_walk(10000+trial);asof=next(iter(frames.values())).index[-1];base=build_radar(frames,asof)\n        for arm,data in [(\'random_walk_null\',frames),(\'injected_3pct\',inject(frames,base.events))]:\n            radar=base if arm==\'random_walk_null\' else build_radar(data,asof)\n            table,_,family=q2_tables(data,radar.events,asof,horizons=(1,),fees=(20,),resamples=args.resamples)\n            target=table[table[\'Mẫu hình\']==\'Bao trùm tăng\'].iloc[0]\n            rows.append(dict(trial=trial,seed=10000+trial,arm=arm,p=target.all_p,p_trend=target.trend_p,q=target.all_q_fixed,q_trend=target.trend_q_fixed,n=target[\'Đủ dữ liệu\'],family=family,\n                             any_q=bool(((table.all_q_fixed<.05)|(table.trend_q_fixed<.05)).any())))\n        if (trial+1)%10==0:print(\'Mô phỏng\',trial+1,\'/\',args.repetitions,flush=True)\n        pd.DataFrame(rows).to_csv(out/\'replications.csv\',index=False,encoding=\'utf-8-sig\')\n    result=pd.DataFrame(rows);summary=[]\n    for arm,g in result.groupby(\'arm\'):\n        for col in [\'p\',\'p_trend\',\'q\',\'q_trend\']:\n            values=g[col].dropna();count=int((values<.05).sum());low,high=wilson_interval(count,len(values))\n            summary.append(dict(arm=arm,metric=col,valid=len(values),rejected=count,rate=count/len(values) if len(values) else None,ci_low=low,ci_high=high))\n    pd.DataFrame(summary).to_csv(out/\'calibration_summary.csv\',index=False,encoding=\'utf-8-sig\')\n    sources=[Path(__file__)]+list((ROOT/\'src/analytics\').glob(\'*.py\'))+list((ROOT/\'src/finance\').glob(\'*.py\'))\n    (out/\'design.json\').write_text(json.dumps(dict(simulated=True,seed_start=10000,repetitions=args.repetitions,resamples=args.resamples,days=650,symbols=6,block_size=20,\n        python=platform.python_version(),numpy=np.__version__,pandas=pd.__version__,\n        source_hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources},primary=\'bullish_engulfing, h=1, 20 bps\',\n        null=\'independent Gaussian log random walk with independent overnight and intraday innovations\',\n        control=\'inject +3% into next-day close after ORIGINAL null engulfing labels; propagate price level, then rerun detection and study\',\n        caveats=[\'positive control not realistic market or online strategy\',\'h=1 calibration does not validate h=3/5/10/20\',\'raw p nominal .05; BY conservative, not expected to reject exactly .05\',\'small Monte Carlo sample has broad uncertainty\']),ensure_ascii=False,indent=2),encoding=\'utf-8\')\n    print(pd.DataFrame(summary).to_string(index=False))\n\n\nif __name__==\'__main__\':main()\n', 'tests/test_research_protocol.py': "import numpy as np\nimport pandas as pd\nimport pytest\nfrom analytics.event_study import event_outcomes\nfrom analytics.multiple_testing import fdr_by\nfrom finance.indicators import indicators\nfrom analytics.radar import build_radar\nfrom finance.context import signal_context\nfrom analytics.inference import block_test\nfrom analytics.study import q1_tables, q2_tables\n\n\ndef fixture():\n    dates=pd.bdate_range('2025-01-01',periods=90)\n    f=pd.DataFrame(dict(open=100.,high=103.,low=97.,close=100.,volume=1000.),index=dates)\n    f.loc[dates[61],['open','high','low','close']]=[100,110,90,105]\n    f.loc[dates[62],['open','high','low','close']]=[105,122,101,120]\n    f.loc[dates[63],['open','high','low','close']]=[120,125,80,110]\n    e=pd.DataFrame([dict(symbol='FPT',date=dates[60],name='hammer',name_vi='Búa',kind='pattern',bias='bullish')])\n    return f,e\n\n\ndef test_hand_calculated_three_session_path():\n    f,e=fixture();r=event_outcomes({'FPT':f},e,f.index[-1],horizons=(3,),fee_bps=40).iloc[0]\n    assert r.status=='evaluated'\n    assert r.gross==pytest.approx(.10)\n    assert r.net==pytest.approx(110*.998/(100*1.002)-1)\n    assert r.mae==pytest.approx(-.20)\n    assert r.entry_date==f.index[61] and r.exit_date==f.index[63]\n\n\n@pytest.mark.parametrize('case,expected',[('pending','pending'),('missing','missing'),('invalid','invalid'),('issue','invalid')])\ndef test_statuses(case,expected):\n    f,e=fixture();reference=f.copy();asof=f.index[-1];issues=None\n    if case=='pending':asof=f.index[62]\n    if case=='missing':f=f.drop(f.index[62])\n    if case=='invalid':f.loc[f.index[62],'high']=1\n    if case=='issue':issues=pd.DataFrame([dict(symbol='FPT',trading_date=f.index[62],severity='error')])\n    r=event_outcomes({'FPT':f,'REF':reference},e,asof,issues,horizons=(3,)).iloc[0]\n    assert r.status==expected and pd.isna(r.net)\n\n\ndef test_future_prices_events_and_errors_cannot_change_closed_results():\n    f,e=fixture();cut=f.index[70]\n    a=event_outcomes({'FPT':f},e,cut,horizons=(1,3,5,10,20))\n    future=f.copy();future.loc[future.index>cut,['open','high','low','close']]=[10000,11000,9000,10500]\n    extra=e.copy();extra['date']=f.index[80]\n    future_issues=pd.DataFrame([dict(symbol='FPT',trading_date=f.index[80],severity='error')])\n    b=event_outcomes({'FPT':future},pd.concat([e,extra]),cut,issues=future_issues,horizons=(1,3,5,10,20))\n    pd.testing.assert_frame_equal(a,b)\n\n\ndef test_directional_bearish_is_signed_contrast_not_short_profit():\n    f,e=fixture();e['name']='hanging_man';e['bias']='bearish'\n    r=event_outcomes({'FPT':f},e,f.index[-1],horizons=(3,)).iloc[0]\n    assert r.oriented_excess==pytest.approx(-r.excess)\n    assert r.direction_hit==0 and r.gross>0\n\n\ndef test_known_by_vector_nan_and_fixed_family():\n    p=np.array([.01,.04,.03,np.nan]);result=fdr_by(p)\n    np.testing.assert_allclose(result[:3],[.055,.07333333333333333,.07333333333333333])\n    assert np.isnan(result[3])\n    assert np.all(fdr_by(p,n_tests=10)[:3]>=result[:3])\n    assert np.isnan(fdr_by([np.nan])[0])\n    with pytest.raises(ValueError):fdr_by([1.1])\n\n\ndef test_conditional_baseline_and_indicators_no_future():\n    rng=np.random.default_rng(13);dates=pd.bdate_range('2025-01-01',periods=150)\n    close=100*np.exp(np.cumsum(rng.normal(0,.01,len(dates))))\n    f=pd.DataFrame(dict(open=np.r_[100,close[:-1]],close=close,volume=1000.),index=dates)\n    f['high']=f[['open','close']].max(axis=1)*1.01;f['low']=f[['open','close']].min(axis=1)*.99\n    e=pd.DataFrame([dict(symbol='FPT',date=dates[80],name='hammer',name_vi='Búa',kind='pattern',bias='bullish')])\n    r=event_outcomes({'FPT':f},e,dates[-1],horizons=(1,),fee_bps=0).iloc[0]\n    t=indicators(f).trend_t.shift(1)\n    eligible=np.arange(len(f))>=11\n    controls=[]\n    for i in range(len(f)-1):\n        if eligible[i] and t.iloc[i]<=-1:controls.append(f.close.iloc[i+1]/f.open.iloc[i+1]-1)\n    assert r.n_conditional_baseline==len(controls)\n    assert r.conditional_baseline_net==pytest.approx(np.mean(controls))\n    first=indicators(f.iloc[:81]);changed=f.copy();changed.iloc[81:,changed.columns.get_loc('close')]*=10\n    pd.testing.assert_frame_equal(first,indicators(changed).iloc[:81])\n\n\ndef test_radar_rejects_gap_and_quality_error_without_future_leakage():\n    f,e=fixture();cut=f.index[70]\n    # Nến thân nhỏ này chắc chắn có tín hiệu trung tính khi đủ lịch sử.\n    f.loc[:,['open','high','low','close']]=[100,103,97,100]\n    broken=f.drop(f.index[60])\n    issues=pd.DataFrame([dict(symbol='FPT',trading_date=f.index[70],severity='error')])\n    result=build_radar({'FPT':broken,'REF':f},cut,issues)\n    chosen=result.events[result.events.symbol=='FPT']\n    assert not chosen[chosen.date.between(f.index[61],cut)].shape[0]\n    assert len(result.missing_sessions)==1\n    assert result.latest.set_index('symbol').loc['FPT','status']=='Nến bị lỗi chất lượng'\n    changed=f.copy();changed.loc[changed.index>cut,['open','high','low','close']]*=10\n    pd.testing.assert_frame_equal(build_radar({'REF':f},cut).events,build_radar({'REF':changed},cut).events)\n\n\ndef test_context_exact_next_session_and_past_indicators():\n    f,e=fixture();event=e.iloc[0].to_dict();day=event['date'];nxt=f.index[61]\n    initial=signal_context(f,event,day,f.index)\n    assert initial['status']=='Chờ xác nhận'\n    later=f.copy();later.loc[nxt,['open','high','low','close']]=[100,110,99,109]\n    result=signal_context(later,event,nxt,f.index)\n    assert result['status']=='Đã xác nhận'\n    assert result['ema20']==initial['ema20']\n    assert result['volume_ratio']==initial['volume_ratio']\n    missing=signal_context(later.drop(nxt),event,f.index[62],f.index)\n    assert missing['status']=='Thiếu nến xác nhận'\n\n\ndef test_bootstrap_keeps_no_signal_dates_and_is_reproducible():\n    calendar=pd.bdate_range('2025-01-01',periods=240)\n    signal=pd.Series(np.random.default_rng(31).normal(.001,.01,30),index=calendar[::8])\n    dense=signal.reindex(calendar)\n    implicit=block_test(signal,calendar,block_size=10,resamples=199,seed=44)\n    explicit=block_test(dense,block_size=10,resamples=199,seed=44)\n    assert implicit==explicit\n    assert implicit['n_dates']==30\n    assert implicit['mean']==pytest.approx(signal.mean())\n    assert block_test(signal.iloc[:19],calendar,resamples=199)['n_dates']==19\n    assert np.isnan(block_test(signal.iloc[:19],calendar,resamples=199)['p'])\n\n\ndef test_fixed_study_family_and_q1_include_absent_patterns():\n    f,e=fixture();e['name_vi']='Búa (Hammer)'\n    year,symbol=q1_tables(e)\n    assert year.shape[0]==19 and symbol.shape[0]==19\n    assert year.to_numpy().sum()==symbol.to_numpy().sum()==1\n    table,details,family=q2_tables({'FPT':f},e,f.index[-1],resamples=99)\n    assert family==280 and len(table)==19*5*2\n    assert len(details)==10\n    assert table[['all_q_fixed','trend_q_fixed']].isna().all().all()\n", 'docs/RESEARCH_GUIDE.md': '# Hoàn thiện nghiên cứu Q1–Q3\n\nBản cập nhật này ưu tiên khả năng tái lập và kiểm tra thống kê. Không triển khai Q4 (học máy), không tuyên bố đã chia dữ liệu 70%/30% hoặc đã kiểm định ngoài mẫu. SSI đã được giảng viên chấp thuận làm nguồn dữ liệu của đồ án.\n\n## 1. Cài bản cập nhật trên Windows\n\nDừng Streamlit bằng Ctrl+C. Giải nén gói cập nhật vào thư mục gốc `vn30-candlestick-radar` để có file `scripts/maintenance/upgrade_research.py`. Không tạo thêm một tầng thư mục dự án.\n\nChạy từng dòng trong PowerShell; không dán dấu `PS>`, `>>` hoặc dấu gạch chéo ở cuối dòng:\n\n```powershell\nSet-Location C:\\Users\\KIEU\\vn30-candlestick-radar\n.\\.venv\\Scripts\\python.exe scripts/maintenance/upgrade_research.py --check\n.\\.venv\\Scripts\\python.exe scripts/maintenance/upgrade_research.py\n.\\.venv\\Scripts\\python.exe -m pytest tests/test_research_protocol.py -q\n.\\.venv\\Scripts\\python.exe -m pytest -q\n```\n\nTrình cài kiểm tra cú pháp toàn bộ mã trước khi thay thế và lưu bản cũ vào `archive/backups/research_<thời điểm>/`. Cấu trúc giao diện trong `src/app/main.py` được giữ nguyên; chỉ cập nhật câu mô tả kỳ hạn cũ nếu có. `.env`, SQLite và tác vụ cập nhật giá không bị thay thế. Trình cài yêu cầu phiên bản dashboard đã tích hợp `render_event_research`; nếu thiếu sẽ dừng và báo rõ. Không chạy lại các script nâng cấp cũ sau bản này vì chúng có thể khôi phục module cũ.\n\nNếu cần quay lại, dùng đường dẫn manifest được trình cài in ra:\n\n```powershell\n.\\.venv\\Scripts\\python.exe scripts/maintenance/upgrade_research.py --restore archive/backups/research_<thời điểm>/manifest.json\n```\n\nKhôi phục sẽ đưa các file trong bản cập nhật về trạng thái trước khi cài, kể cả ghi đè chỉnh sửa mới trên các file đó. Hãy lưu riêng các chỉnh sửa cần giữ trước khi khôi phục.\n\n## 2. Chạy nghiên cứu chính thức\n\n```powershell\n.\\.venv\\Scripts\\python.exe scripts/run_study.py --db storage/radar.db --sensitivity\n```\n\nLuồng này đọc SQLite, không gọi API và không sửa dữ liệu. Chạy sau khi ingest kết thúc. Mặc định dùng toàn bộ lịch sử đã có của 30 mã trong `src/data/universe_vn30.txt`; ngày cuối không vượt ngày đã đóng theo chốt 15:00 UTC+7. Chốt ngày cụ thể khi hoàn thiện báo cáo, ví dụ:\n\n```powershell\n.\\.venv\\Scripts\\python.exe scripts/run_study.py --db storage/radar.db --asof 2026-11-18 --sensitivity --out report/tables_final\n```\n\nChỉ dùng ví dụ 18/11 nếu DB thực sự đã chứa dữ liệu đó. Ngày nghỉ không tự tạo thêm nến. Nếu một mã trong rổ chưa có bất kỳ OHLC nào, chương trình dừng; thiếu phiên riêng lẻ được xử lý ở mức từng quan sát.\n\nQ2 chạy 39.999 lượt bootstrap cho mỗi tương phản, có thể mất vài phút tùy máy. Không đóng terminal khi đang tính Q2. Có thể dùng `--resamples 999 --out report/smoke` để thử luồng; không lấy kết quả chạy thử này làm bảng kiểm định chính thức. p có độ phân giải hữu hạn; với họ 280 giả thuyết, số lượt quá ít làm q rất bảo thủ. Chọn số lượt trước khi xem kết quả, không tăng dần chỉ để đạt ý nghĩa.\n\nCác file đầu ra:\n\n| File | Vai trò trong báo cáo |\n|---|---|\n| `q1_pattern_year.csv` | Q1: tần suất từng mẫu hình theo năm |\n| `q1_pattern_symbol.csv` | Q1: tần suất từng mẫu hình theo mã |\n| `signals.csv` | Nhãn lịch sử, gồm mẫu hình hoàn chỉnh và setup |\n| `q2_summary.csv` | Q2: lợi suất, mức nền, hướng lý thuyết, CI/p/q |\n| `q2_outcomes.csv` | Dữ liệu từng nhãn × kỳ hạn × mức phí, gồm trạng thái loại/chờ |\n| `q3_summary.csv` | Q3: tỷ lệ setup hai nến hoàn thành ở phiên tiếp theo, CI Wilson |\n| `q3_outcomes.csv` | Từng setup và trạng thái kết quả |\n| `sensitivity_counts.csv` | Số nhãn theo 7 cấu hình ngưỡng |\n| `sensitivity_q3.csv` | Q3 theo các cấu hình ngưỡng |\n| `manifest.json` | Ngày chốt, rổ mã, tham số, phiên bản thư viện, hash mã/dữ liệu/bảng |\n\nKhông sửa tay CSV để khớp kết luận. Đóng băng một thư mục `tables_final` cùng manifest; lấy tất cả số liệu nghiên cứu từ lần chạy đó. `input_snapshot_sha256` băm các khung dữ liệu đã đọc trong cùng giao dịch, kể cả khi SQLite dùng WAL; `db_sha256` chỉ băm file DB vật lý tại lúc tạo manifest.\n\n## 3. Q2 được định nghĩa thế nào?\n\n- Kỳ hạn thống nhất: **1, 3, 5, 10, 20 phiên thị trường**.\n- Tín hiệu ở t; vào giá mở cửa t+1; ra giá đóng cửa t+h. h=1 nghĩa là mở cửa và đóng cửa cùng phiên t+1.\n- Lợi suất gộp: `close[t+h] / open[t+1] - 1`.\n- Nếu tổng phí hai chiều là c (bps), lợi suất long sau phí: `close[t+h]*(1-c/20000)/(open[t+1]*(1+c/20000))-1`. Chạy cả **20 và 40 bps**; đây là giả định chi phí, không phải xác nhận mức phí thực tế của mọi công ty chứng khoán.\n- MAE long: `min(0, min(low[t+1:t+h])/open[t+1]-1)`. Đây là mức bất lợi của quan sát long, không phải drawdown danh mục.\n- Mức nền thường: cùng mã/kỳ hạn/phí, lấy trung bình các cửa sổ đủ lịch sử và đủ nến tương lai hợp lệ.\n- Mức nền điều kiện: với mẫu hình đảo chiều, chỉ lấy cửa sổ có thống kê t xu hướng ngược chiều trước mẫu hình, đúng độ dịch theo số nến của bộ nhận diện. Marubozu và mẫu hình trung tính không có điều kiện đảo chiều này nên dùng nền thường.\n- `oriented_excess` = long sau phí trừ nền, nhân +1 với hướng tăng và −1 với hướng giảm. `oriented_conditional_excess` dùng nền điều kiện. Số dương thể hiện hướng tương phản phù hợp lý thuyết. **Đây không phải lợi nhuận bán khống**, và không phải tỷ suất lợi nhuận của một chiến lược được giao dịch thật.\n- `direction_hit` = giá tăng với nhãn tăng / giá giảm với nhãn giảm, tính trước phí; giá không đổi không được tính thành công. So sánh với tỷ lệ đúng hướng của các cửa sổ nền cùng mã. Nhãn trung tính không có định nghĩa đúng hướng.\n- Mức nền dùng toàn bộ lịch sử đóng đến ngày chốt; đây là nghiên cứu trong mẫu, không phải mô phỏng ra quyết định trực tuyến. Khả năng ước lượng ngoài mẫu chưa được chứng minh.\n\nTrạng thái quan sát: `pending` nếu chưa có đủ h phiên; `missing` nếu cửa sổ thiếu nến so với lịch thị trường ước lượng; `invalid` nếu OHLC sai hoặc có lỗi chất lượng mức error; `evaluated` nếu đủ dữ liệu hợp lệ. Không tự nhảy qua một phiên thiếu để lấy một ngày muộn hơn.\n\n**Đơn vị lấy trung bình:** long return, MAE, tỷ lệ đúng hướng và chênh tỷ lệ được mô tả theo từng nhãn; các tương phản dùng kiểm định được lấy trung bình chéo mã trong cùng ngày, rồi lấy trọng số đều theo ngày tín hiệu. Do đó không suy ra hai cách tổng hợp phải bằng nhau.\n\n## 4. Cách đọc các cột kiểm định\n\n| Nhóm cột | Ý nghĩa và đơn vị |\n|---|---|\n| `bias` | bullish/bearish/neutral |\n| `all_mean`, `trend_mean` | Chênh nền đã đổi dấu theo hướng; đơn vị tỷ lệ, 0,01 = 1% |\n| `all_low/high`, `trend_low/high` | Khoảng bootstrap 95% của tương phản tương ứng |\n| `all_p`, `trend_p` | p một phía, giả thuyết đối là tương phản đúng hướng > 0 |\n| `all_q_fixed`, `trend_q_fixed` | BY trên toàn bộ họ nghiên cứu đã chốt |\n| `direction_hit_rate` | Tỷ lệ giá đi đúng hướng, trước phí, theo nhãn |\n| `baseline_direction_rate`, `trend_baseline_direction_rate` | Tỷ lệ đúng hướng của mức nền tương ứng |\n| `direction_hit_gap`, `trend_direction_hit_gap` | Chênh tỷ lệ đúng hướng; đây mới là mô tả, chưa có kiểm định riêng |\n| Cột tiếng Việt có `(%)` | Đã nhân 100 |\n| `p bootstrap`, `q BY` | Kiểm định tương phản long hai phía cũ để tương thích UI; không phải cặp kết quả chính cho câu hỏi hướng lý thuyết |\n\nBáo cáo Q2 dùng `all_q_fixed` và `trend_q_fixed`. Họ chốt trước: 14 mẫu hình có hướng × 5 kỳ hạn × 2 mức phí × 2 mức nền = **280 giả thuyết**. Các giả thuyết không đủ quan sát vẫn thuộc họ; q của chúng để trống. Nhãn trung tính vẫn có thống kê mô tả nhưng không được ép vào kiểm định hướng lý thuyết. Không chọn riêng mức phí/nền/kỳ hạn có kết quả đẹp nhất.\n\nBootstrap vòng tròn theo khối 20 phiên trên lịch đầy đủ; ngày không tín hiệu vẫn có mặt dưới dạng NaN, không bị nén thành các ngày liên tiếp giả tạo. CI là percentile; p lấy từ phân phối bootstrap đã trừ trung bình. Chỉ tính suy luận khi có ít nhất 30 nhãn và 20 ngày tín hiệu. Hạn chế còn lại: ước lượng mức nền được giữ cố định khi bootstrap; tính dừng, độ dài khối, phụ thuộc chéo mã và số quan sát nhỏ ảnh hưởng tính chính xác. BY chỉ có ý nghĩa khi p đầu vào hợp lệ; không tự sửa được mọi sai lệch của mô hình lấy mẫu.\n\nDashboard có thể đổi ngày, mã và phạm vi nên q tương tác thay đổi. UI chỉ phục vụ khám phá; ảnh chụp giao diện không thay thế bảng nghiên cứu cố định.\n\n## 5. Phân tích độ nhạy\n\nĐổi từng tham số một so với mặc định: doji_k 0,05 / 0,15; trend_t 0,75 / 1,25; avg_window 20; strict_gap True. Cộng với mặc định là 7 cấu hình. Xem số nhãn và Q3 (n, tỷ lệ, CI); không chọn lại cấu hình nhận diện theo xác suất hoặc lợi suất cao nhất. Đây là khảo sát độ vững cục bộ, không phải quét mọi tổ hợp.\n\nDoji và các biến thể có thể trùng nhau trên một nến; tổng số nhãn Q1 không phải số ngày tín hiệu độc lập. `doji_k` không trực tiếp điều khiển mọi điều kiện của Sao mai/Sao hôm, nên Q3 có thể không đổi khi chỉ đổi tham số này.\n\nCác ngưỡng nhận diện là định nghĩa vận hành của đồ án, chưa có bằng chứng chúng tối ưu. Ngưỡng khối lượng 1,2 lần và quy tắc vượt đỉnh/đáy trong thẻ tín hiệu là quy tắc theo dõi do tác giả đặt; ngưỡng khối lượng đã cho chỉnh trên UI. Vùng tô ±0,5% chỉ hỗ trợ hiển thị. Thống kê t 10 phiên mới là tiêu chí xu hướng của bộ nhận diện; lợi suất 5 phiên là mô tả bổ trợ.\n\n## 6. Mô phỏng hiệu chuẩn\n\n```powershell\n.\\.venv\\Scripts\\python.exe scripts/research/calibrate.py --repetitions 300 --resamples 3999 --out report/calibration_final\n```\n\nLuồng này tạo **dữ liệu mô phỏng**, không đọc dữ liệu SSI: 6 mã, 650 phiên, random walk log với biến động độc lập qua đêm/trong phiên. Chạy lại nhận diện và nghiên cứu cho cả nhánh null và nhánh cấy hiệu ứng +3% vào đóng cửa phiên tiếp theo sau nhãn Bao trùm tăng ban đầu; truyền thay đổi mức giá sang những phiên sau, dựng lại high/low hợp lệ, rồi nhận diện lại. Positive control này là công cụ kiểm tra độ nhạy, không phải thị trường thực tế hoặc chiến lược khả thi.\n\nMô phỏng hiện giới hạn h=1, phí 20 bps, họ 28 giả thuyết. Đại lượng chính định trước là Bao trùm tăng; file replications còn ghi có bất kỳ q<0,05 trong họ hay không. Chưa kiểm chứng đầy đủ h=3/5/10/20 hoặc các mẫu hình khác. 300 lần vẫn chỉ là mở rộng sơ bộ; phải đọc CI và mẫu số đủ điều kiện. Tỷ lệ bác bỏ p dưới null được so với mức danh nghĩa 5%; BY thường bảo thủ hơn và **không được yêu cầu bác bỏ đúng 5%**.\n\nBản chạy kiểm tra đã hoàn thành 100 vòng, 3.999 bootstrap:\n\n- Nhánh null có 60 vòng đủ điều kiện cho đại lượng chính; 4/60 p<0,05 = 6,67%, CI Wilson 95% 2,62–15,93%; 0/60 q<0,05.\n- Nhánh +3% có 35 vòng đủ điều kiện; 35/35 được phát hiện, cả p và q; CI Wilson 90,11–100%.\n- Mẫu số hai nhánh khác nhau vì cấy hiệu ứng và nhận diện lại làm thay đổi số nhãn. Không báo cáo đây là power 100% trên toàn bộ 100 vòng.\n- CI còn rộng; kết quả chưa chứng minh kiểm định được hiệu chuẩn đúng, cũng không chứng minh mẫu hình có ích trên thị trường thật.\n\nĐầu ra: `replications.csv`, `calibration_summary.csv`, `design.json`. Lưu nguyên seed/cấu hình và không ghi số liệu mô phỏng như kết quả SSI.\n\n## 7. Kết quả minh họa trên bản DB được tải lên\n\nNgày cuối: **16/11/2026**; rổ cố định 30 mã. Đây không phải DB mới nhất trên máy Windows của bạn. Gói kết quả mẫu được đặt trong thư mục riêng, không dùng để ghi đè bảng final.\n\n- Không có tương phản hướng lý thuyết nào đạt q<0,05 sau BY trên họ 280 giả thuyết. Điều này không chứng minh hiệu ứng bằng 0; nghiên cứu chưa có đủ bằng chứng theo tiêu chuẩn đã chọn, đặc biệt với mẫu hình hiếm.\n- Q3 Sao mai: 7/107 = 6,54%, CI Wilson 3,20–12,89%; Sao hôm: 28/256 = 10,94%, CI 7,68–15,35%. Đây là xác suất **hoàn thành mẫu hình**, không phải xác suất sinh lời. Wilson giả định quan sát Bernoulli độc lập; phụ thuộc giữa mã/ngày có thể làm khoảng này lạc quan.\n- Qua 7 cấu hình khảo sát: Sao mai khoảng 6,34–8,74%; Sao hôm 10,94–12,36%; số quan sát và độ rộng CI cũng thay đổi. Không suy diễn “ổn định hoàn toàn” chỉ từ khoảng dao động nhỏ.\n\n## 8. Những việc tiếp theo để nộp bài\n\n1. Cài bản cập nhật, chạy test; nếu có lỗi, giữ nguyên traceback và không tiếp tục lấy bảng lỗi làm kết quả.\n2. Nạp dữ liệu đến phiên đã đóng, chạy kiểm tra chất lượng đang có và giải thích các warning còn lại. Không tự xóa warning chỉ để bảng trống.\n3. Chạy `run_study.py --sensitivity` một lần với ngày chốt và thư mục final, lưu manifest.\n4. Viết phần phương pháp trước, rồi phần kết quả Q1/Q2/Q3 từ bảng final; nêu rõ không triển khai Q4.\n5. Giữ giới hạn: lịch thị trường suy từ dữ liệu chứ chưa phải lịch sàn; thành phần VN30 cố định hiện tại không phải rổ theo từng thời điểm; cần xác minh nguồn giá đã điều chỉnh cổ tức/chia tách chưa; chưa mô phỏng trượt giá/thanh khoản/khớp lệnh khi trần sàn; chưa đánh giá ngoài mẫu. Phân tích độ nhạy ngưỡng không thay thế xác minh dữ liệu.\n6. Chụp hình dashboard để minh họa thao tác, không lấy số liệu có bộ lọc tùy ý thay cho bảng final. Mở dashboard bằng lệnh dưới.\n7. Cuối cùng quay video ingest thật rồi đọc SQLite trên dashboard; che thông tin xác thực, không đưa `.env` vào bài nộp.\n\n```powershell\n.\\.venv\\Scripts\\python.exe -m streamlit run src/app/main.py\n```\n\n## 9. Tài liệu tham khảo đã kiểm tra thông tin thư mục\n\nKiểm tra ngày 20/11/2026 qua nhà xuất bản/metadata thư mục. Các tài liệu là nền tảng phương pháp hoặc nghiên cứu liên quan; không phải bằng chứng các ngưỡng tự chọn của đồ án đã được tối ưu.\n\n1. Benjamini, Y., & Yekutieli, D. (2001). The control of the false discovery rate in multiple testing under dependency. *The Annals of Statistics, 29*(4), 1165–1188. https://doi.org/10.1214/aos/1013699998 — thông tin đối chiếu tại https://cris.tau.ac.il/en/publications/the-control-of-the-false-discovery-rate-in-multiple-testing-under/\n2. Politis, D. N., & Romano, J. P. (1992). A circular block-resampling procedure for stationary data. In R. LePage & L. Billard (Eds.), *Exploring the Limits of Bootstrap* (pp. 263–270). Wiley. Đối chiếu danh mục tác giả: https://profiles.stanford.edu/joseph-romano?tab=publications . Không nhầm với bài “The Stationary Bootstrap” năm 1994 hoặc một chương khác về confidence regions năm 1992.\n3. Wilson, E. B. (1927). Probable inference, the law of succession, and statistical inference. *Journal of the American Statistical Association, 22*(158), 209–212. https://doi.org/10.1080/01621459.1927.10502953\n4. MacKinlay, A. C. (1997). Event studies in economics and finance. *Journal of Economic Literature, 35*(1), 13–39. https://ideas.repec.org/a/aea/jeclit/v35y1997i1p13-39.html — không gán DOI chưa xác minh.\n5. Marshall, B. R., Young, M. R., & Rose, L. C. (2006). Candlestick technical trading strategies: Can they create value for investors? *Journal of Banking & Finance, 30*(8), 2303–2323. https://doi.org/10.1016/j.jbankfin.2005.08.001\n'}

VERSION='research-1.0.0'
ROOT=Path(__file__).resolve().parents[2]


def checked_path(rel):
    path=(ROOT/rel).resolve()
    if not path.is_relative_to(ROOT):raise ValueError('Đường dẫn ngoài dự án: '+str(rel))
    return path


def sha(data):return hashlib.sha256(data).hexdigest()


def atomic(path,data):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+'.research-'+uuid.uuid4().hex+'.tmp')
    try:
        tmp.write_bytes(data);os.replace(tmp,path)
    finally:
        tmp.unlink(missing_ok=True)


def restore(manifest):
    manifest=checked_path(manifest)
    if not manifest.is_relative_to(ROOT/'archive/backups'):raise ValueError('Manifest phải nằm trong archive/backups')
    info=json.loads(manifest.read_text(encoding='utf-8'))
    if info.get('version')!=VERSION:raise ValueError('Manifest không thuộc bản cập nhật này')
    records=info['files'];backup=manifest.parent
    allowed=set(PAYLOADS)|{'src/app/main.py'}
    for record in records:
        if record['path'] not in allowed:raise ValueError('File không thuộc bản cập nhật')
        if record['existed']:
            old=(backup/'originals'/record['path']).read_bytes()
            if sha(old)!=record['old_sha256']:raise ValueError('Bản sao lưu sai hash: '+record['path'])
    for record in reversed(records):
        dest=checked_path(record['path'])
        if record['existed']:atomic(dest,(backup/'originals'/record['path']).read_bytes())
        else:dest.unlink(missing_ok=True)
    print('Đã khôi phục',len(records),'file từ',manifest)


def main():
    parser=argparse.ArgumentParser(description='Cài nghiên cứu Q1–Q3; sao lưu mã trước khi ghi, không sửa SQLite hoặc .env.')
    parser.add_argument('--check',action='store_true',help='Chỉ kiểm tra và liệt kê file')
    parser.add_argument('--restore',help='Đường dẫn manifest sao lưu để quay lại')
    args=parser.parse_args()
    if not (ROOT/'pyproject.toml').is_file():raise ValueError('Đặt script tại scripts/maintenance/upgrade_research.py bên trong dự án')
    if args.restore:
        if args.check:raise ValueError('Không kết hợp --check và --restore')
        restore(args.restore);return
    main_path=ROOT/'src/app/main.py'
    main_bytes=main_path.read_bytes();source=main_bytes.decode('utf-8-sig')
    ast.parse(source,filename=str(main_path))
    if 'render_event_research' not in source:raise ValueError('Dashboard chưa tích hợp render_event_research; cần bản dashboard có signal_workspace trước khi cài nghiên cứu')
    db_source=(ROOT/'src/data/db.py').read_text(encoding='utf-8-sig')
    db_tree=ast.parse(db_source)
    names={n.name for n in ast.walk(db_tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
    if not {'connect_readonly','load_ohlc'}.issubset(names):raise ValueError('src/data/db.py thiếu connect_readonly/load_ohlc; cần bản vá SQLite trước khi cài')
    if not (ROOT/'src/finance/patterns.py').exists():raise ValueError('Thiếu src/finance/patterns.py')
    blobs={rel:text.encode('utf-8') for rel,text in PAYLOADS.items()}
    # Chỉ sửa câu mô tả kỳ hạn; giữ nguyên cấu trúc, menu, style và mã main của người dùng.
    revised=source.replace('Lợi suất 5/10/20 phiên','Lợi suất 1/3/5/10/20 phiên')
    if revised!=source:
        bom=bytes.fromhex('efbbbf') if main_bytes.startswith(bytes.fromhex('efbbbf')) else b''
        blobs['src/app/main.py']=bom+revised.encode('utf-8')
    for rel,data in blobs.items():
        checked_path(rel)
        if rel.endswith('.py'):compile(data.decode('utf-8-sig'),rel,'exec')
    changes={rel:data for rel,data in blobs.items() if not checked_path(rel).exists() or checked_path(rel).read_bytes()!=data}
    print('Dự án:',ROOT)
    for rel in changes:print('  cập nhật:',rel)
    if args.check:
        print('Kiểm tra OK;',len(changes),'file sẽ thay đổi; chưa ghi file.');return
    if not changes:print('Đã có đầy đủ bản nghiên cứu này.');return
    backup=ROOT/'archive/backups'/('research_'+datetime.now().strftime('%Y%m%d_%H%M%S')+'_'+uuid.uuid4().hex[:6])
    backup.mkdir(parents=True)
    records=[]
    for rel,data in changes.items():
        dest=checked_path(rel);existed=dest.exists();old=dest.read_bytes() if existed else None
        if existed:
            copy=backup/'originals'/rel;copy.parent.mkdir(parents=True,exist_ok=True);copy.write_bytes(old)
        records.append(dict(path=rel,existed=existed,old_sha256=sha(old) if existed else None,new_sha256=sha(data)))
    manifest=backup/'manifest.json'
    manifest.write_text(json.dumps(dict(version=VERSION,files=records),ensure_ascii=False,indent=2),encoding='utf-8')
    try:
        for rel,data in changes.items():atomic(checked_path(rel),data)
    except Exception:
        restore(str(manifest));raise
    print('Đã cài Q1–Q3. Sao lưu:',manifest.relative_to(ROOT))
    print(r'Tiếp theo: .\.venv\Scripts\python.exe -m pytest tests/test_research_protocol.py -q')
    print(r'Xuất bảng: .\.venv\Scripts\python.exe scripts/run_study.py --sensitivity')


if __name__=='__main__':
    try:main()
    except Exception as exc:
        print('Không thể cập nhật:',exc,file=sys.stderr);sys.exit(1)
